import{esc,modal,toast}from './ui.js';
import{localCities,mergeCities,searchCities,locateCity,latestRequest}from './city-data.js';
export function openCityDialog(currentCity,onSelect){
 modal('<div class="modal-head"><h2>Ваш город</h2><button class="icon-button" data-close aria-label="Закрыть">×</button></div><form id="city-search"><div class="field"><label for="city-name">Город</label><input id="city-name" placeholder="Например, Медина" required minlength="2" maxlength="120" autocomplete="off" aria-controls="city-results"></div><div id="city-results" aria-label="Подсказки городов"></div><p id="city-status" class="muted city-status" role="status"></p><button class="button">Найти город</button></form><button class="button secondary city-geolocate" id="geolocate">Определить местоположение</button><p class="city-privacy-note">При определении города координаты получат BigDataCloud и Open-Meteo.</p><details class="city-privacy"><summary>О местоположении</summary><p>Геолокация используется для времени намаза и Киблы. BigDataCloud получает координаты и сетевой адрес для определения города и улучшения геолокации; Open-Meteo определяет часовой пояс. Можно выбрать город вручную.</p><a href="https://www.bigdatacloud.com/privacy-policy" target="_blank" rel="noopener">Конфиденциальность BigDataCloud</a><p>Поиск городов: Open-Meteo / GeoNames.</p></details>');
 const dialog=document.getElementById('modal'),form=document.getElementById('city-search'),input=document.getElementById('city-name'),results=document.getElementById('city-results'),status=document.getElementById('city-status'),geo=document.getElementById('geolocate');
 const requests=latestRequest();let timer,closed=false;
 const active=()=>!closed&&dialog.open&&input.isConnected;
 const cancel=()=>{clearTimeout(timer);requests.cancel();geo.disabled=false;geo.textContent='Определить местоположение'};
 const cleanup=()=>{closed=true;cancel()};dialog.addEventListener('close',cleanup,{once:true});
 const select=city=>{if(!active())return;input.value=city.name;cancel();onSelect(city)};
 function show(cities){results.replaceChildren();for(const city of cities){const button=document.createElement('button');button.type='button';button.className='list-button city-suggestion';const same=cities.filter(other=>other.name.toLocaleLowerCase('ru')===city.name.toLocaleLowerCase('ru')).length>1;button.innerHTML='<span>'+esc(city.name)+'</span>'+(same?'<small>'+esc([city.country,city.admin1].filter(Boolean).join(' · '))+'</small>':'');button.onclick=()=>select(city);results.append(button)}}
 async function search(query,request,local){try{const found=await searchCities(query,{signal:request.signal});if(!active()||!request.current())return;const cities=mergeCities(local,found);show(cities);status.textContent=cities.length?'':query.length===2?'Введите ещё одну букву для поиска.':'Город не найден. Попробуйте другое написание.'}catch{if(!active()||!request.current())return;status.textContent=local.length?'':'Не удалось найти город. Проверьте интернет и повторите поиск.'}}
 function changed(immediate=false){cancel();const query=input.value.trim(),request=requests.start(),local=localCities(query,currentCity);show(local);status.textContent='';if(query.length<2)return;if(!immediate&&query.length===2){if(!local.length)status.textContent='Введите ещё одну букву для поиска.';return}if(!local.length)status.textContent='Ищем город…';if(immediate)search(query,request,local);else timer=setTimeout(()=>search(query,request,local),300)}
 input.addEventListener('compositionstart',cancel);input.addEventListener('input',event=>{if(!event.isComposing)changed()});input.addEventListener('compositionend',()=>changed());input.addEventListener('keydown',event=>{if(event.key==='ArrowDown'&&results.firstElementChild){event.preventDefault();results.firstElementChild.focus()}});results.addEventListener('keydown',event=>{if(!['ArrowDown','ArrowUp'].includes(event.key))return;event.preventDefault();const buttons=[...results.children],index=buttons.indexOf(document.activeElement);if(event.key==='ArrowUp'&&index===0)input.focus();else buttons[Math.max(0,Math.min(buttons.length-1,index+(event.key==='ArrowDown'?1:-1)))]?.focus()});form.onsubmit=event=>{event.preventDefault();changed(true)};
 geo.onclick=()=>{if(!navigator.geolocation){toast('Геолокация недоступна. Выберите город вручную.');return}cancel();const request=requests.start();geo.disabled=true;geo.textContent='Определяем…';status.textContent='';navigator.geolocation.getCurrentPosition(async position=>{if(!active()||!request.current())return;geo.textContent='Находим город…';try{const city=await locateCity(position.coords,{signal:request.signal});if(active()&&request.current())select(city)}catch{if(active()&&request.current()){geo.disabled=false;geo.textContent='Определить местоположение';status.textContent='Не удалось определить город. Введите его название вручную.'}}},error=>{if(!active()||!request.current())return;geo.disabled=false;geo.textContent='Определить местоположение';status.textContent=error.code===1?'Разрешите доступ к местоположению или введите город вручную.':'Местоположение не получено. Введите город вручную.'},{enableHighAccuracy:true,timeout:15000,maximumAge:0})};
}
